def literal_chunks(t,indent):
 starts=list(re.finditer(r'^'+re.escape(indent)+r'let (\S+)',t,re.M));result={}
 for i,m in enumerate(starts):
  end=starts[i+1].start() if i+1<len(starts) else len(t)
  block=t[m.start():end]
  if indent=='    ' and i==len(starts)-1:block=block.split('\n    ∀ y xRef')[0]
  if indent=='        ' and i==len(starts)-1:block=block.split('\n        Measurable (Function.uncurry D)')[0]
  result[m.group(1)]=block.rstrip()
 return result
